    [2199] = "Lleva 5 lingotes de plata a Talvash del Kissel a Forjaz.",
    [2200] = "Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño.",
    [2201] = "Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio. A través del diario, sabes que... *El rubí está escondido en una zona de Forjatiniebla con barricadas. *El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza. *El zafiro obra en poder de Grimlok, el líder de los enanos, según él mismo afirma.",
    [2202] = "Llévale 12 setas moradas a Musgofusión en Kargath.",
    [2203] = "Usa las vasijas de taumaturgia vacías con los dragones guardianes abrasados encontrados en las Tierras Inhóspitas. Cuando las hayas llenado, llévaselas a Jarkal Musgofusión en Kargath.",
    [2204] = "Obtén una fuente de energía del constructo más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz.",
    [2205] = "Entrega el paquete de Keryn Sylvius al maestro Mathias Shaw que está en el Cuartel de Ventormenta.",
    [2206] = "Encuentra al maestro de embarcadero Defias y recupera el horario de envíos para el maestro Mathias Shaw.",
    [2218] = "Ve a Forjaz y habla con Hulfdan Barbanegra.",
    [2238] = "Encuentra a Onin MacHammar cerca de Gnomeregan.",
    [2239] = "Lleva el informe de Onin a Hulfdan a Forjaz.",
    [2240] = "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta.",
    [2241] = "Llévale la rosa de Jannok a Syurna, que está en Darnassus.",
    [2242] = "Encuentra a Sethir el Ancestro y ve a contarle todo lo que descubras a Syurna.",
    [2258] = "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de piedra a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas.",
    [2259] = "Localiza a Erion Sombrusurro en Darnassus.",
    [2260] = "Viaja a la Ciudad de Ventormenta y habla con Renzik Cuchillo.",
    [2278] = "Habla con el guardapiedras y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon.",
    [2279] = "Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz.",
    [2280] = "Lleva la reproducción en miniatura de los Discos de Norgannon a uno de los sabios de Cima del Trueno.",
    [2281] = "Adéntrate en Villa del Lago, en las Montañas Crestagrana, y habla con Lucius.",
    [2282] = "Abre la caja fuerte de Lucius y llévale la muestra de robo a Villa del Lago.",
    [2283] = "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar.  Puede que el collar esté estropeado.",
    [2284] = "Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman.",
    [2298] = "Viaja a Ventormenta y busca a Renzik Cuchillo.",
    [2299] = "Viaja a Forjaz y habla con Hulfdan Barbanegra.",
    [2300] = "Viaja a Ventormenta y busca a Renzik Cuchillo.",
    [2318] = "Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas.",
    [2338] = "Préstale el collar a Jarkal. A cambio, te traducirá el diario.",
    [2339] = "Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un constructo de Uldaman. Por el diario sabes… * Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla. * Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza. * Que Grimlok, el jefe trogg, se ha quedado con el zafiro.",
    [2340] = "Entrégale el collar y la gema salvaje a Dran Droffers en Orgrimmar.",
    [2341] = "Habla con Jarkal Musgofusión en Kargath.",
    [2342] = "Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas.",
    [2359] = "Roba la Llave de la Torre Defias, entra en la Torre Defias y descubre qué contiene el Cofre del Bosque del Ocaso. Lleva toda la información que encuentres a Mathias Shaw de Ventormenta. Lee el diario de Kearnen para saber cómo acceder a la torre.",
    [2360] = "Ve a Páramos de Poniente y encuentra a la agente Kearnen para dar parte.",
    [2378] = "Viaja a Orgrimmar y habla con Shenthul, que estará en el Circo de las Sombras.",
    [2379] = "Habla con Zando'zan en el Circo de las Sombras.",
    [2380] = "Ve a Orgrimmar, al Circo de las Sombras, y habla con Shenthul.",
    [2381] = "Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir un G.E.A.Q. y herramientas de ladrones del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión. Si te atacaran unos loros anormalmente agresivos, ¡usa el G.E.A.Q.!",
    [2382] = "Ve a Trinquete y habla con Desdio el Desdichado.",
    [2383] = "Lee el Pergamino sencillo y habla con Frang en el Valle de los Retos.",
    [2398] = "Encuentra a Baelog en Uldaman.",
    [2418] = "Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas.",
    [2438] = "Llévale el cazasueños esmeralda a Tallonkai Cruzarraíz, que está en Dolanaar.",
    [2439] = "Lleva tu vale de recompensa a Dinita Quebrantarrocas, que está en las Arcas de Forjaz.",
    [2440] = "Llévale este vale de recompensa a Bena Pezuña Invernal, que está en Cima del Trueno.",
    [2458] = "Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada. Cuando veas la torre, usa la pistola de bengalas para avisar de tu llegada. Lanza 2 bengalas y acércate al capataz Fizzule para darle el /saludo de los Mano Destrozada. Tienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce.",
    [2459] = "Tallonkai Cruzarraíz de Dolanaar quiere que mates a 7 místicos Tuercepinos y encuentres la joya perdida.",
    [2460] = "Da el saludo de los Mano Destrozada a Shenthul.",
    [2478] = "Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 vigías de Ventura y Cía. Asesina al Gran Supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar, él te dará más instrucciones.",
    [2479] = "Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de Zanzil a Serge Hinott. Para ir, coge el zepelín a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos. ¡Sigue las indicaciones!",
    [2480] = "Espera a que Serge Hinott te cure.",
    [2498] = "Rellian Verdeguja quiere que hables con Denalan, que está en el Lago Al'Ameth.",
    [2499] = "Denalan, que está en el Lago Al'Ameth, quiere que cojas el tumor gigantesco que tiene Roblegüello.",
    [2500] = "Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar.",
    [2501] = "Usa las vasijas de taumaturgia en los dragones guardianes abrasados de las Tierras Inhóspitas.  Llévaselas a Ghak Sanadón a Thelsamar.",
    [2518] = "La sacerdotisa A'moora del Templo de la Luna de Darnassus quiere que le lleves las hilanderas plateadas de Lady Sathrah.",
    [2519] = "La hermana Aquinne quiere que hables con la sacerdotisa A'moora en el Templo de la Luna.",
    [2520] = "La sacerdotisa A'moora quiere que coloques las hilanderas plateadas de Lady Sathrah en la fuente que hay en el interior del templo, y que después vayas a verla de nuevo.",
    [2521] = "En tus viajes por Las Tierras Devastadas, si te encontraras con una esfera draenetista perfecta, llévasela a Kum'isha el Coleccionista. Ten cuidado, esta gema es uno de los cristales más raros de todo Azeroth. Cualquier criatura de estas tierras podría tener una. Se te recompensará por cada esfera draenetista perfecta que consigas.",
    [2522] = "Encuentra una esfera draenetista perfecta y llévasela a Kum'isha el Coleccionista.",
