    [3378] = "Lleva la oración a Elune a Astarii Buscaestelar a Darnassus.",
    [3379] = "Mata a los furtivos Sedaumbría de La Garganta de Fuego. Nilith cree que son 5. Ve a ver a Nilith en La Garganta de Fuego cuando hayas terminado.|n",
    [3380] = "Encuentra a Marvon Buscarroblones en Tanaris.",
    [3382] = "Defiende a la capitana Vanessa Beltis, su tripulación y los pasajeros del Explorador del horizonte frente al ataque de los nagas. La capitana Vanessa Beltis tiene que sobrevivir.",
    [3385] = "Mata al maestro de comercio Kovic y a su esbirro, Clonk. Lleva su cartera a Nilith.|n",
    [3402] = "Habla con Vizzklick en Gadgetzan.|n",
    [3441] = "Escucha a Velarok Espada del Viento.",
    [3442] = "Lleva 4 corazones de llama y 4 globos de aceite gólem a Velarok Espada del Viento.",
    [3443] = "Lleva 8 dagas chapadas en torio a Velarok Espada del Viento.",
    [3444] = "Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete.",
    [3445] = "Encuentra a Marvon Buscarroblones en Tanaris.",
    [3446] = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.",
    [3447] = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.",
    [3448] = "Habla con Tymor en Forjaz.",
    [3449] = "Haz calcos de la Runa de Beth'Amara, la Runa de Jin'yael, la Runa de Markri y la Runa de Sael'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Luzfusil para que recoja los calcos.",
    [3450] = "Habla con Xiggs Luzfusil en Forjaz.",
    [3451] = "Habla con Xiggs Luzfusil para que te dé una pistola de bengalas en Forjaz.",
    [3452] = "Lleva un Símbolo de Ragnaros a Velarok Espada del Viento.",
    [3453] = "Espera a que Velarok Espada del Viento termine la Antorcha de Reprensión.",
    [3454] = "Coge la Antorcha de Reprensión.",
    [3461] = "Devuelve el juego de calco a Tymor, que está en Forjaz.",
    [3462] = "Habla con mi enviado, el escudero Maltrake.",
    [3463] = "Entra en las 4 torres del centinela e incéndialas con la Antorcha de Reprensión.",
    [3481] = "Abre el cofre.",
    [3501] = "Llévale a Kum'isha fragmentos de draenetista imperfecta y te recompensará por cada fragmento entregado.",
    [3502] = "Llévale a Kum'isha fragmentos de draenetista imperfecta. Cualquier forma de monstruo de Las Tierras Devastadas podría llevar uno de estos fragmentos.",
    [3504] = "Entrega la carta sellada a Ag'tor Puñosangre en Azshara.",
