    [3510] = "Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc.",
    [3511] = "Llévale el temple a Loramus Thalimedes.|n",
    [3512] = "Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Contacto Espiritual.",
    [3513] = "Llévale el pergamino rúnico de la torre de vigilancia norte en Los Baldíos.",
    [3514] = "Mata al jefe de El Cubil del Espolón, Rynthariel el Llavero.",
    [3517] = "Encuentra la tablilla de Beth'Amara, la tablilla de Jin'yael, la tablilla de Markri y la tablilla de Sael'hai para Jediga, en Valormok.",
