    [3630] = "Si quieres aprender más sobre ingeniería gnoma, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.",
    [3631] = "Habla con Strahad Farsan en Los Baldíos.",
    [3632] = "Si quieres saber más sobre el tema, llévale el Manual de disciplinas de ingeniería aI maestro manitas Sobrechispa a Forjaz.",
    [3633] = "Si quieres aprender más cosas sobre la ingeniería de los goblins, lleva el Manual de disciplinas de ingeniería a Nixx Muellepiñón en Gadgetzan.",
    [3634] = "Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.",
    [3635] = "Si quieres saber más sobre ingeniería gnómica, llévale el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus de Bahía del Botín.",
    [3636] = "El Arzobispo Bendictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno.",
    [3637] = "Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín.",
    [3638] = "Si quieres convertirte en un ingeniero goblin, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y habla de nuevo con Nixx Muellepiñón de Gadgetzan.",
    [3639] = "Llévale 20 bombas grandes de hierro, 20 cartuchos de dinamita compacta y 5 ovejas explosivas a Nixx Muellepiñón de Gadgetzan.",
