    [3642] = "Si quieres convertirte en <un ingeniero/una ingeniera> gnomo, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y vuelve a hablar con Oglethrope Obnoticus en la Bahía del Botín.",
    [3643] = "Lleva 6 tubos de mitril, un escopo preciso y 2 muñecos-diana avanzados a Oglethorpe Obnoticus en la Bahía del Botín.",
    [3661] = "Recoge 15 plumas de lechúcico de las Tierras del Interior y llévaselas a Erelas Cieloámbar a la Aldea Rut'theran.",
    [3681] = "Ve a Ventormenta y habla con Duthorian Rall.",
    [3701] = "Ve a las Ruinas de Thaurissan, en las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa al historiador regio Archesonus.",
    [3702] = "Escucha al historiador regio Archesonus relatar la historia de Thaurissan.",
    [3741] = "Encuentra el collar de Hilary y llévaselo a Villa del Lago.",
    [3761] = "Llévale 20 muestras de la tierra de Un'Goro a Ghede, que está en el Alto de los Ancestros de Cima del Trueno.",
    [3762] = "Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno.",
    [3763] = "Ve a Darnassus y habla con el archidruida Fandral Corzocelada.",
    [3764] = "Lleva 20 muestras de tierra de Un'Goro Soil a Jenal, que está en el Enclave Cenarion de Darnassus.",
    [3765] = "Ve a ver a Gershala Noctusurro en Auberdine.",
    [3781] = "Lleva el vale para semillas del archidruida a Mathrengyl Garroso al Enclave Cenarion de Darnassus.",
    [3782] = "Llévale este vale para semillas a Bashana Runatótem, que está en Cima del Trueno.",
    [3783] = "Reúne 10 pieles gruesas de yeti para Umi Risitas en Vista Eterna.",
    [3784] = "Habla con el archidruida Hamuul Runatótem en Cima del Trueno.",
    [3785] = "Utiliza una bolsa de siempreverde con 1 paquete de semillas de Tharlendris y 2 muestras de tierra de Un'Goro para intentar cultivar mañagrana. Lleva 10 plantas de mañagrana a Mathrengyl Garroso a Darnassus.",
    [3786] = "Mete en la bolsa de siempreverde un paquete de Tharlendris y dos muestras de tierra de Un'Goro para cultivar muestras de mañagrana. Llévale 10 mañagranas a Bashana Runatótem, que está en Cima del Trueno.",
    [3787] = "Habla con Quintis Jonguja en el Bastión Plumaluna.",
    [3788] = "Habla con Quintis Jonguja del Bastión Plumaluna.",
    [3789] = "Habla con el archidruida Fandral Corzocelada en Darnassus.",
    [3790] = "Habla con el archidruida Fandral Corzocelada en Darnassus.",
    [3791] = "Lleva 10 plantas de mañagrana a Quintis Jonguja al Bastión Plumaluna.",
    [3801] = "Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad.",
    [3802] = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjafina.",
    [3821] = "Adéntrate en Las Estepas Ardientes y averigua qué le ha ocurrido a Sha'ni Colminilludo.",
    [3822] = "Recupera la alianza de la nariz de Sha'ni de Krom'Grul y llévasela a Thal'trak en Kargath. Busca por las diferentes cuevas y minas de la Roca Machacamiedo.",
    [3823] = "Mata a 15 ogros magos Pirontraña, 7 ogros Pirontraña y 7 ogros brutos Pirontraña y vuelve junto a Oralius cuando hayas acabado.",
    [3824] = "Encuentra a Gor'tesh, en el algún lugar al oeste de la Roca Machacamiedo. Mata a Gor'tesh y llévale entonces la cabeza cortada de Gor'tesh a Oralius en Las Estepas Ardientes.",
    [3825] = "Coge la cabeza cortada de Gor'tesh y colócala en lo alto de la Roca Machacamiedo. Busca un montículo de tierra blanda para clavar la pica.",
    [3841] = "Ve a Las Mil Agujas y habla con Quentin.",
    [3842] = "Lleva 2 elixires de la entereza a Quentin a Las Mil Agujas.",
    [3843] = "Lleva tu huevo de duende dardo frágil a las Tierras del Interior y habla con Agnar Domabestias, pero date prisa: si tardas más de 1 hora en encontrarlo, la cría que hay en el huevo morirá.",
    [3844] = "Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada.",
    [3845] = "Examina los objetos de la talega y devuélveselos a su propietario.",
    [3861] = "Consigue comida para pollos y ve con el pollo que has conocido. Cuando lo encuentres, /dórale la píldora antes de darle la comida.",
    [3881] = "Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro.",
    [3882] = "Lleva 8 huesos de dinosaurio a Chispik Nilminer en el Cráter de Un'Goro.",
    [3883] = "Utiliza el vial raspador para recoger una Muestra de pared de la colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes. Lleva la Muestra de pared de la colmena a Hol'anyee Marshal en el Cráter de Un'Goro.",
    [3884] = "Devuelve el diario a Williden Marshal en algún lugar del Cráter de Un'Goro.",
    [3901] = "Mata a 12 esqueletos armadóseos y cuando lo hayas hecho, vuelve a buscar al sacerdote de las Sombras Sarvis a Camposanto.",
    [3902] = "Busca 6 piezas de mercancías extraviadas por Camposanto y los alrededores y llévaselas al guardia de la muerte Saltain.",
    [3903] = "Habla con Milly Osworth.",
    [3904] = "Lleva 8 cajas de uva recogida a Milly Osworth a la Abadía de Villanorte.",
    [3905] = "Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte.",
    [3906] = "Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo.",
    [3907] = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón.",
    [3908] = "Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno.",
    [3909] = "Busca a Gregan Vomitabrebaje en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno.",
    [3912] = "Ve al cementerio a las afueras de Gadgetzan y utiliza el Elixir de Videre. Sigue las demás instrucciones de Donova para encontrar a Gaeriyan.",
    [3913] = "Resucita y busca la lápida de la que te habló Gaeriyan.",
    [3914] = "Entrega la Espada superior a Linken en el Cráter de Un'Goro.",
    [3921] = "Llévale el churumbele roto a Wenikee Tuercasmil.",
    [3922] = "Llévale 15 engranajes a Wenikee Tuercasmil en Los Baldíos.",
    [3923] = "Llévale el churumbele roto y maltrecho a Rilli Gapegajoso en Orgrimmar.",
    [3924] = "Llévale el manual del churumbele a Rilli Gapegajoso en Orgrimmar.",
    [3941] = "Encuentra a J.D. Collie en la cueva del Refugio de Marshal.",
    [3942] = "Encuentra a Eridan Vientoazul en el sur de Frondavil.",
    [3961] = "Lleva el Tótem plateado de Aquementas a Linken, en el Refugio de Marshal.",
    [3962] = "Viaja a Cresta del Penacho en Llamas, al sur del Refugio de Marshal. Busca a Correfuego y utiliza el Tótem para eliminar su aura protectora. Cuando le hayas derrotado, coge la Llama Dorada de la cueva.",
    [3981] = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra. Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar.",
    [3982] = "Defiende a Gor'shak.",
    [4001] = "Habla con Kharan Martillo Poderoso y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar. Recuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana.|n",
    [4002] = "Si aceptas la misión, habla con Thrall.",
    [4003] = "Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo.",
    [4004] = "¡Vuelve junto a Thrall!",
    [4005] = "Lleva el Libro de Aquor, las zarpas plateadas y el corazón de Troncoferro a Tanaris. Utiliza el Libro de Aquor para invocar Aquementas. Cuando tengas el tótem completo llévaselo a J.D. Collie en el Refugio de Marshal.",
    [4021] = "Llévale una pieza del estandarte de Krom'zar a Regthar Portamorta, al oeste de El Cruce.",
    [4022] = "Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Velarok Espada del Viento.",
    [4023] = "Demuéstrale a Cyrus Therepentio lo que vales. Te da la impresión de que Cyrus ya sabe que no eres digno.",
    [4024] = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar. Solo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia fiera. Llévale la esencia fiera recubierta a Cyrus Therepentio.",
    [4061] = "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania. Recuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos.",
    [4062] = "Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus. Recuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este.",
    [4063] = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los gólems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres <un adivino/una adivina>.",
    [4081] = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.",
    [4082] = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.",
    [4084] = "Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil.",
    [4101] = "Lleva 15 unidades de sangre ámbar a Arathandris Cielargente a Frondavil.",
    [4102] = "Lleva 15 unidades de sangre ámbar a Maybess Brisafluvial a Frondavil.",
    [4120] = "Talo Pezuñahendida, del Campamento Mojache de Feralas, quiere que mates a 12 griseznos Zarpira y 12 devastadores Zarpayel de Frondavil.",
    [4121] = "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego. Recuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido. También tendrás que entregarle a Lexlort los grilletes de torio.",
    [4122] = "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra. Cuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.",
    [4123] = "Llévale el Corazón de la Montaña a Maxwort Suprandor en Las Estepas Ardientes.",
    [4124] = "Ve al Bastión Plumaluna y habla con Ginro Mechogar.",
    [4125] = "Localiza el bote del mensajero por la costa de Feralas.",
    [4126] = "Llévale la receta perdida de Cebatruenos a Ragnar Cebatruenos en Kharanos.",
    [4127] = "Vuelve al Bastión Plumaluna y enseña a Ginro Mechogar el cuchillo perdido que encontraste.",
    [4128] = "Habla con Ragnar Cebatruenos.",
    [4129] = "Lleva el cuchillo perdido a Quintis Jonguja al Bastión Plumaluna.",
    [4130] = "Ve al Bastión Plumaluna y habla con Ginro Mechogar.",
    [4131] = "Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas.",
    [4132] = "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjainquina! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea.",
    [4133] = "Habla con la nigromante Vivian Latumba en Kargath.",
    [4134] = "Llévale la receta perdida de Cebatruenos a Vivian Latumba en Kargath.",
    [4135] = "Ahora que has descubierto el rastro de Raschal, adéntrate en Las Entrañas Retorcidas y encuéntrale... o encuentra lo que quede de él. Según la nota, debes dirigirte al sur de los campamentos de los Zarpaleña.",
    [4136] = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes.",
    [4141] = "Recoge 15 pétalos de sangre y ve a ver a Muigin.",
    [4142] = "Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas.",
    [4143] = "Reúne 5 muestras de bruma Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro.",
    [4145] = "Caza 5 latigadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal.",
    [4146] = "Entrega el Controlador descargado y 5 muestras de bruma Atal'ai a Larion, en el Refugio de Marshal.",
    [4147] = "Viaja hasta el taller de Marvon Buscarroblones en Trinquete.",
    [4161] = "Recoge 7 patas de araña pequeña para Zarrin, que está en Dolanaar.",
    [4181] = "Si quieres saber más sobre el tema, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón a Gadgetzan.",
    [4182] = "Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea.",
    [4183] = "Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Salomón.",
    [4184] = "Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon. Vive en el Castillo de Ventormenta.",
    [4185] = "Habla con el Alto Señor Bolvar Fordragon después de hablar con Lady Katrana Prestor.",
    [4186] = "Lleva el decreto de Bolvar al magistrado Salomón en la Villa del Lago.",
    [4201] = "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la maestra Nagmara en las Profundidades de Roca Negra.",
    [4223] = "Habla con el alguacil Maxwell en Las Estepas Ardientes.",
    [4224] = "Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea. Recuerdas que el alguacil Maxwell comentó algo sobre buscarlo en una cueva hacia el norte.",
    [4241] = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor. Recuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor.",
    [4242] = "Dale las malas noticias a alguacil Maxwell.",
    [4243] = "Encuentra a Memo 01 en el Cráter de Un'Goro.",
    [4244] = "Encuentra una envoltura de mitril y reúnete de nuevo con Memo 01 en el Cráter de Un'Goro.",
    [4245] = "Lleva a Memo 01 de vuelta con Karna Tipirrem al Cráter de Un'Goro.",
    [4261] = "Escolta a Arei y luego habla con Kayneth Ventoleve que está en Canción del Bosque, en la parte este de Vallefresno.",
    [4262] = "Mata al gran maestro Pyron y vuelve junto a Jalinda Sprig. Recuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí.",
    [4263] = "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!",
    [4264] = "Puede que acabes de toparte con algo que le interesaría ver al alguacil Windsor. Puede que haya esperanza, después de todo.",
    [4265] = "Libera a Raschal de la vaina de los Zukk'ash. Vuelve al Bastión Plumaluna con Ginro Mechogar e infórmale de que Raschal está bien.",
    [4266] = "Habla con Shandris Plumaluna del Bastión Plumaluna.",
    [4267] = "Lleva el informe de Raschal a Gracina Poderespíritu a Darnassus.",
    [4281] = "Lleva el paquete sin entregar a Díscolo Falfildel a Thalanaar.",
    [4282] = "Devuélvele al alguacil Windsor la información perdida. <name> alguacil Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjira.",
    [4283] = "Oralius quiere 50 medallones Roca Negra. Con toda probabilidad encontrarás estos medallones en los orcos de Las Estepas Ardientes.",
    [4284] = "Recoge 7 cristales de poder de cada color: rojo, azul, amarillo y verde. Llévaselos a J.D. Collie en el Refugio de Marshal.",
    [4285] = "Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro.",
    [4286] = "Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve junto a Oralius cuando hayas completado esta tarea. Se da por sentado que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estos inventos de riñoneras.",
    [4287] = "Descubre la localización de la Torre de Cristal del Este en el Cráter de Un'Goro.",
    [4288] = "Descubre la localización de la Torre de Cristal del Oeste.",
    [4289] = "Llévale 2 pieles de gorila de Un'Goro, 2 pieles de vapuleador de Un'goro y 2 pieles de tronador de Un'Goro a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro.",
    [4290] = "Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.",
    [4291] = "Llévale 2 glándulas de feromonas de ravasaurio a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.",
    [4292] = "Utiliza el contenido de la bolsa de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.",
    [4293] = "Recoge muestras de babosa de Frondavil de cualquiera de las babosas que encuentres en Frondavil. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras están más corruptas. Llévale 5 de las muestras de Frondavil corruptas que encuentres al químico Fuely.",
    [4294] = "Recoge muestras de babosa de Un'Goro de cualquiera de las babosas que encuentres en el Cráter de Un'Goro. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras son más puras. Llévale 5 de las muestras de Un'Goro puras que encuentres al químico Fuely.",
    [4296] = "Llévale la transcripción de la tablilla a Maxwort Suprandor en Las Estepas Ardientes.",
    [4297] = "Lleva 5 costillas de acechador Melenargenta a Agnar Domabestias a las Tierras del Interior.",
    [4298] = "Habla con Agnar Domabestias en las Tierras del Interior.",
    [4300] = "Lleva 8 garras de ravasaurio blanco a Jes'rimon a Orgrimmar.",
    [4301] = "Llévale la piel de U'cha a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro.",
    [4321] = "Habla en un momento con J.D. Collie.",
    [4322] = "Ayuda al alguacil Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al alguacil Maxwell si lo consigues.",
    [4324] = "Habla con Yuka Llavenrosca en Las Estepas Ardientes.",
    [4341] = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillazo. <name> rey dijo que estaba prisionero allí; busca una cárcel.",
    [4342] = "Escucha la historia de Kharan Martillazo.",
    [4361] = "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce.",
    [4362] = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan.",
    [4363] = "Regresa a Forjaz y habla con el rey Magni Barbabronce.",
    [4402] = "Lleva a Galgar 10 manzanas de cactus. Recuerdas haberle oído decir que se encuentran junto a los cactus.",
    [4421] = "Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión.",
    [4441] = "Viaja a Darnassus y utiliza el vial de Eridan para recoger agua bendita del Templo de la Luna. Vuelve a Eridan con el vial lleno.",
    [4442] = "Vuelve a hablar con Eridan dentro de un momento.",
    [4449] = "Mata a 8 geólogos Hierro Negro y lleva 15 piezas de seda a la persona encerrada en los baños de La Garganta de Fuego.",
    [4450] = "Coge el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris.",
    [4451] = "Busca en La Garganta de Fuego para ver cómo se usa la llave del anexo de Grimesilt.",
    [4485] = "Habla con Duthorian Rall en Ventormenta.",
    [4486] = "Habla con Duthorian Rall en Ventormenta.",
    [4487] = "Habla con Strahad Farsan en Trinquete.",
    [4488] = "Habla con Strahad Farsan en Trinquete.",
    [4489] = "Habla con Strahad Farsan en Trinquete.",
    [4490] = "Habla con Strahad Farsan en Trinquete para aprender a invocar a un malignoecus.",
    [4491] = "Lleva a Ringo con Spraggle Habitus en el Refugio de Marshal. Si Ringo se desmaya utiliza la cantimplora de Spraggle para reanimarlo.",
    [4492] = "Encuentra a Ringo en la Cresta del Penacho en Llamas.",
    [4493] = "Ve a Gadgetzan y habla con el alquimista Morterozugg.",
    [4494] = "Habla con el alquimista Morterozugg en Gadgetzan.",
    [4495] = "Encuentra a Iverron cerca de la cueva que hay al norte.",
    [4496] = "Llévale una glándula secretora de olor de Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.",
    [4501] = "Mata a 10 Pterrordáctilos y a 15 Pterrordáctilos dementes. Cuando lo hayas hecho habla con Spraggle Habitus en el Refugio de Marshal.",
    [4502] = "Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete.",
    [4503] = "Recoge 8 escamas membranosas de diemetradón y 8 escamas membranosas de Pterrordáctilo para Shizzle, en el Refugio de Marshal.",
    [4504] = "Reúne 12 muestras de alquitrán superpegajoso para Tran'rek de Gadgetzan.",
    [4505] = "Recoge una muestra de agua corrupta de la Poza de la Luna de los sátiros Fuego de Jade y llévasela a Winna Hazzard al Puesto del Veneno.",
    [4506] = "Lleva el gatito de Winna a la poza de la luna corrupta, libéralo allí y luego llévaselo a Winna. Cuando hayas vuelto con Winna, haz clic en el felino para dárselo.",
    [4507] = "Derrota a la reina de la colmena Gorishi cuando hayas conseguido que salga al exterior. Llévale el cerebro de la reina Gorishi al alquimista Morterozugg de Gadgetzan.",
    [4508] = "Llévale el informe de Morterozugg de Un'Goro a Gracina Poderespíritu, que está en Darnassus.",
    [4509] = "Llévale el informe de Morterozugg de Un'Goro a Zilzibin Drumlore, que está en Orgrimmar.",
    [4510] = "Lleva el vale del banco a Idriana, al banco de Darnassus.",
    [4511] = "Lleva el vale a Karus al banco de Orgrimmar.",
    [4512] = "Consigue 6 jarros llenos de moco maldito y 6 jarros llenos de moco corrupto pra Laris Cadenapartida en Forjaz.",
    [4513] = "Lleva 10 tarros de muestra pura a Laris Cadenartida a Forjaz. Si no los encuentras, habla con Laris.",
    [4521] = "Trull Fallarruina de Frondavil quiere que mates 15 lechubestias enfurecidas y 15 lechubestias pulgosas.",
    [4542] = "Entrégale el mensaje urgente a Vigiarisco Cuernolargo en el Poblado Viento Libre.",
    [4581] = "Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque.",
    [4621] = "Mata al maestro de flota Cuernomarino y al Barón Baron Revilgaz de la Bahía del Botín y, a continuación, vuelve a reunirte con el maestro de flota Firallon abordo del Valle carmesí, cerca de la costa de la Vega de Tuercespina.",
    [4641] = "Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek reside en El Cubil, un edificio que está al oeste.",
    [4642] = "Llévale una muestra del moco fusionado al químico Fuely de Entrañas.",
    [4681] = "Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde.",
    [4701] = "Viajar hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del lupo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al lupo.",
    [4721] = "Trull Fallarruina de Frondavil quiere que caces 10 lechubestias rabiosas en Cuna del Invierno.",
    [4722] = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4723] = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4724] = "Mata a Halycon, la maestra de la manada de los huargos Hacha de Sangre.",
    [4725] = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.",
    [4726] = "Llévale 8 esencias de cría y el Draco Incarcinatrix 900 a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes.",
    [4727] = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4728] = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4729] = "Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado.",
    [4730] = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4731] = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.",
    [4732] = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4733] = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.",
    [4734] = "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero.",
    [4735] = "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes.",
    [4736] = "Habla con Menara Nadiz en Los Baldíos.",
    [4737] = "Habla con Menara Nadiz en Los Baldíos.",
    [4738] = "Habla con Menara Nadiz en Los Baldíos.",
    [4739] = "Habla con Menara Nadiz en Los Baldíos.",
    [4740] = "Encuentra y mata al múrloc conocido como Viscoso.  Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua. Informa de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine.",
    [4741] = "Trull Fallarruina de Frondavil quiere que caces 13 lechubestias lunadón.",
    [4742] = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan. Los generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre.",
    [4743] = "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad. Este es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!",
    [4761] = "Ve a Auberdine y habla con Thundris Tejevientos.",
    [4762] = "Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua. Vuelve a Auberdine a buscar a Thundris Tejevientos con la muestra del Río Fonroca.",
    [4763] = "Llena el cuenco purificador vacío en la poza de la luna de Auberdine. Recoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolg Bosque Negro. Mezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor. Coge el talismán de Corrupción y llévaselo a Thundris Tejevientos a Auberdine.",
    [4764] = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes.",
    [4765] = "Llévale el cajón de Crestabuena a Remington Crestabuena en Ventormenta.",
    [4766] = "Habla con Mayara Alasol en Las Estepas Ardientes.",
    [4767] = "Consigue 10 huevos de dracoleón Nido Alto para Elu en el Poblado Viento Libre.",
    [4768] = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Latumba en Kargath.",
    [4769] = "Habla con la maga oscura Vivian Latumba Vivian Latumba.",
    [4770] = "Saca a Pao'ka Velocimontés de Nido Alto y después habla con Motega Pirocabello en Campamento del Tramo Blanco.",
    [4771] = "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink.",
    [4781] = "Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina.",
    [4782] = "Regresa junto a Menara Nadiz en Los Baldíos.",
    [4783] = "Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos.",
    [4784] = "Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos.",
    [4786] = "Espera a que Menara Nadiz complete tu túnica y vuelve entonces a hablar con ella.",
    [4787] = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.",
    [4788] = "Llévale la quinta y sexta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris.",
    [4808] = "Entrégale la carta de Tinkee a Felnok Acerovera.",
    [4809] = "Llévale 8 cuernos de quimera venfresco sin fisuras a Felnok Acerovera.",
    [4810] = "Llévale el paquete de Felnok a Tinkee Vaporio en Las Estepas Ardientes.",
    [4811] = "Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura.  Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea.",
    [4812] = "Llena el vial de agua vacío en la poza de la luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura.",
    [4813] = "Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea.",
    [4821] = "Devuélvele el huevo extraño a Hagar Relampafauce, que está en el Poblado Viento Libre.",
    [4841] = "Mata a 12 exploradores Galak, 10 vaqueros Galak y 6 cazavientos Galak, y después ve a ver de nuevo a Vigiarisco Cuernolargo al Poblado Viento Libre.",
    [4842] = "Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle.",
    [4861] = "Localiza el campamento arrasado y los suministros de Jaron Tallapiedras en la parte sur de Cuna del Invierno.",
    [4862] = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler. Yo diría que se pueden encontrar estos huevos cerca de arañas.",
    [4863] = "Encuentra el carro destrozado de Jaron Tallapiedras.",
    [4864] = "Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico que robó el amuleto del que te habló Jaron. Lleva los Suministros de Jaron y el Amuleto de plumas azules a Jaron Tallapiedras en el refugio de Cuna del Invierno.",
    [4865] = "Cuéntale a Motega Pirocabello lo que has descubierto.",
    [4866] = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti.",
    [4867] = "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh.",
    [4881] = "Avisa a Kanati Nubegris, que está en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida.",
    [4882] = "Lleva el Collar de plumas azules a Trull Fallarruina en el Puesto del Veneno.",
    [4883] = "Lleva el Collar de plumas azules a Nara Bravacrín.",
    [4901] = "Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Eralas Cieloámbar de Aldea Rut'theran.",
    [4902] = "Habla con el archidruida Fandral Corzocelada de Darnassus.",
    [4903] = "Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión.",
    [4904] = "Saca a Lakota Canzalvaje de Cumbre de la Nube Negra y después habla con Thalia Pielámbar, que está en el Poblado Viento Libre.",
    [4906] = "Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho.",
    [4907] = "Habla con Tinkee Vaporio.",
    [4921] = "Encuentra a la esposa de Mankrik y llévala a El Cruce.",
    [4941] = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall. Recuerdas haber visto a Eitrigg en la Cámara de Thrall.",
    [4961] = "Mata al demonio del orbe y luego habla con Tabetha.",
    [4962] = "Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago capturado a Menara Nadiz en Los Baldíos.",
    [4963] = "Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal capturado a Menara Nadiz en Los Baldíos.",
    [4964] = "Espera a Menara Nadiz para completar el orbe de Dar'Orahil y vuelve entonces a hablar con ella.",
    [4965] = "Habla con Menara Nadiz en Los Baldíos.",
    [4966] = "Defiende a Kanati Nubegris contra el ataque de los centauros.",
    [4967] = "Habla con Menara Nadiz en Los Baldíos.",
    [4968] = "Habla con Menara Nadiz en Los Baldíos.",
    [4969] = "Habla con Menara Nadiz en Los Baldíos.",
    [4970] = "Recoge 5 carnes dentoesquirla y 5 carnes venfresco para Rivern Ventogélido de Cuna del Invierno.",
    [4971] = "Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales. Mata a 15 parásitos temporales y devuélvele el desplazador temporal a Chromie en la posada de Andorhal, en las Tierras de la Peste del Oeste.",
    [4972] = "Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Chromie, en la posada de Andorhal, en las Tierras de la Peste del Oeste.",
    [4973] = "Localiza 5 relojes de Andorhal entre las ruinas de la ciudad y llévaselos a Chromie, en la posada de Andorhal, en las Tierras de la Peste del Oeste.",
    [4974] = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar.",
    [4975] = "Espera a Menara Nadiz para completar el orbe de Noh'Orahil y vuelve entonces a hablar con ella.",
    [4976] = "Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos.",
    [4981] = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou.",
    [4982] = "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad.|n",
    [4983] = "Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath.",
    [4984] = "Destruye 8 lobos malsanos y regresa con Mulgris Riohondo en El Tormento, en las Tierras de la Peste del Oeste.",
    [4985] = "Destruye 8 griseznos malsanos y regresa con Mulgris Riohondo en El Tormento, en las Tierras de la Peste del Oeste.",
    [4986] = "Según la magia con la que está encantada La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion en Darnassus. Pide ayuda a uno de los druidas que encontrarás allí.",
    [4987] = "Según la magia con la que está encantada de La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion de Cima del Trueno. Pide ayuda a uno de los druidas que encontrarás allí.",
    [5001] = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!",
    [5002] = "Viaja a Las Estepas Ardientes y dale la información sobre Bijou al alguacil Maxwell.",
    [5021] = "Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete.",
    [5022] = "Consulta con los agentes reales de Ventormenta para averiguar el paradero de una tal Emma Piedra Mácula. Suele haber un oficial del censo en el Ayuntamiento.",
    [5023] = "Consulta con los supervisores reales de Entrañas para averiguar el paradero de Jeremiah Piedra Mácula. Suele haber un oficial del censo junto a la oficina de registro de hermandades y tabardos.",
    [5041] = "Encuentra los cajones de suministros de El Cruce y devuélveselos a Thork en Los Baldíos.",
    [5047] = "Habla con Malyfous Martilloscuro en Vista Eterna.",
    [5048] = "Encuentra a la Vieja Emma en Ventormenta y descubre si realmente es Emma Piedra Mácula. Si lo es, quizás quiera el paquete que Janice Piedra Mácula hizo para ella.",
    [5049] = "Encuentra a Jeremiah Payson en Entrañas y averigua si en realidad es Jeremiah Piedra Mácula. Si es así, quizás quiera el paquete que Janice Piedra Mácula preparó para él.",
    [5050] = "Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte.",
    [5051] = "Localiza la otra mitad del talismán de la suerte en algún lugar de la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste, y recomponlo. Dale el talismán de la suerte a Janice Piedra Mácula en la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste.",
    [5052] = "Llévale un fragmento ensangrentado a Quebrantadientes en el Campamento Taurajo en Los Baldíos. Reúne más fragmentos ensangrentados si quieres que te bendiga con el poder de Agamaggan.",
    [5054] = "Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Ursius.",
    [5055] = "Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Brumerán.",
    [5056] = "Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que acabes con Shy-Rotam.",
    [5057] = "Lleva la Señal de Ventisca Pezumbría a Melor Pezuñapétrea de Cima del Trueno.",
    [5061] = "Vuelve a Darnassus y enséñale el colgante del león marino a Mathrengyl Garroso.",
    [5062] = "Recoge 10 montones de pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno.",
    [5063] = "Para crear el Almete del Sabio Escarlata deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 8 cristales Arcanos; 5 hilos escarlata encantados. También tendrás que pagar 50 piezas de oro para la elaboración del almete.",
    [5064] = "Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra.",
    [5065] = "Llévale la tercera y cuarta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris.",
    [5066] = "Busca al comandante Ashlam Puñovalor. Su campamento base está situado en el Campamento del Orvallo, al norte de las Montañas de Alterac.",
    [5067] = "Para crear los leotardos arcana deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 cuero prístino de la Bestia; 5 costuras desgarradas de abominación; 5 lingotes de arcanita; 5 líquidos de embalsamar de Levescarcha. También tendrás que pagar 50 piezas de oro para la elaboración del almete.",
    [5068] = "Para crear la coraza Sed de Sangre deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 10 costuras desgarradas de abominación; 5 barras de arcanita; 5 pieles de Sombra. También tendrás que pagar 50 piezas de oro para la elaboración del almete.",
    [5081] = "Viaja a la Cumbre de Roca Negra y destruye al maestro de guerra Voone, al alto señor Omokk y al Señor Supremo Vermiothalak. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo.",
    [5082] = "Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 Vigilantes del cubil Nevada y 8 totémicos Nevada.",
    [5083] = "Lleva el Frasco vacío de piroagua a Donova Cubilnevado de Cuna del Invierno.",
    [5084] = "Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil.",
    [5085] = "Informa sobre tus descubrimientos a Donova Cubilnevado.",
    [5086] = "Recoge 3 gotitas horror tóxico para Donova Cubilnevado de Cuna del Invierno.",
    [5087] = "Encuentra a los corredores Nevada y detenlos antes de que entreguen su cargamento en Poblado Nevada.",
    [5088] = "Mata a Arikara y lleva sus restos y el polvo de incendiaria a Motega Crin de Fuego en el Campamento del Tramo Blanco como prueba de tus actos.",
    [5089] = "Llévale la orden del general Drakkisath al alguacil Maxwell en Las Estepas Ardientes.",
    [5090] = "Busca al comandante Ashlam Puñovalor; su campamento base está en Campamento del Orvallo, al norte de las Montañas de Alterac.",
    [5091] = "Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac.",
    [5092] = "Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas. Vuelve con el comandante Ashlam Puñovalor en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5093] = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.",
    [5094] = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.",
    [5095] = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.",
    [5096] = "Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedra Mácula y el Llanto de Dalson y destruye su tienda de mando. Coloca el estandarte de la Plaga en el campamento y vuelve con el sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5097] = "Con la Antorcha de aviso, marca las torres de Andorhal. Tendrás que estar en la entrada de la torre para poder marcarla. Cuando estén marcadas las cuatro torres, devuelve la Antorcha de aviso al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5098] = "Con la Antorcha de aviso, marca las torres de Andorhal. Tendrás que estar en la entrada de la torre para poder marcarla. Cuando estén marcadas las cuatro torres, devuelve la Antorcha de aviso al sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5102] = "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo.",
    [5103] = "Alguien en este mundo debe de saber qué hacer con estos guanteletes. ¡Suerte!",
    [5121] = "Donova Cubilnevado de Cuna del Invierno quiere que derrotes al Gran Jefe Nevada.",
    [5123] = "Lleva el Diario mal escrito a Donova Cubilnevado de Cuna del Invierno.",
    [5124] = "Lleva a Malyfous Martilloscuro 6 barras de torio encantado, 2 esencias de fuego y 4 rubíes estrellados. También tendrás que entregarle tus guanteletes de placas sin templar.",
    [5126] = "Habla con Lorax. Escucha todo lo que tiene que decirte.|n",
    [5127] = "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pico manchado de sangre sobre su cadáver. Cuando hayas absorbido su alma, el pico estará manchado de alma. También debes encontrar el peto cubierto de runas sin forjar. Lleva el pico manchado de alma y el peto cubierto de runas sin forjar a Lorax en Cuna del Invierno.",
    [5128] = "Lleva el registro escrito de forma rudimentaria a Kelek Guardacielo en el sur de Frondavil.",
    [5141] = "Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Peter Galen, en Azshara. Si completas esta misión tendrás acceso al arte de la peletería dracónica. Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla.",
    [5142] = "Encuentra a Pamela Rutagrana.",
    [5143] = "Lleva 1 jubón de cuero salvaje y 1 casco de cuero salvaje a Caryssia Cazaluna a Feralas. Si completas esta misión, tendrás acceso a las artes de Peletería tribal. Si lo haces, no podrás aprender peletería dragontina ni peletería elemental; asegúrate de que este es el camino que deseas seguir antes de completar la misión.",
    [5144] = "Lleva 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Sarah Peletero a La Garganta de Fuego. Al completar esta tarea aprenderás peletería elemental. Si te dedicas a este arte, no podrás aprender peletería dragontina ni peletería tribal; piénsatelo bien antes de decidirte.",
    [5145] = "Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Thorkaf Dragonojo, en las Tierras Inhóspitas. Si completas esta misión tendrás acceso al arte de la peletería dracónica. Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla.",
    [5146] = "Llévale 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Brumm Pezuña Invernal en las Tierras Altas de Arathi. Cuando completes esta misión tendrás acceso a las artes de peletería elemental. Si completas esta misión, no podrás aprender peletería dragontina ni peletería tribal; asegúrate de que este es el camino que deseas seguir antes de tomarlo.",
    [5147] = "Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña a Vigiarisco Cuernolargo, que está en el Poblado Viento Libre.",
    [5148] = "Lleva un jubón de cuero salvaje y un casco de cuero salvaje a Se'Jib en la Vega de Tuercespina. Completar esta misión te proporcionará acceso a las artes de la peletería tribal. Completar esta misión evitará que aprendas peletería dragontina y peletería elemental. Asegúrate que este es el camino que quieres seguir antes de hacerlo.",
    [5149] = "Encuentra la muñeca de Pamela.",
    [5151] = "Acaba con la bestia y trae de regreso el hipercapacitor y la llave de la jaula a Wizlo Rodabrillante.",
    [5152] = "Habla con Marlene. Está al sur de las Ruinas de Andorhal.",
    [5153] = "Lleva la alianza de Joseph a Chromie.",
    [5154] = "Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal.",
    [5155] = "Entra en Jaedenar y mata a 4 canes Jaedenar, 4 soldados Jaedenar, 6 adeptos Jaedenar y 6 fieles Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil.",
    [5156] = "Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen putraqua corrupta, vuelve con Taronn Plumarroja a Frondavil.",
    [5157] = "Lleva la cantimplora vacía a la poza de la luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil.",
    [5158] = "Lleva el agua de poza de luna corrupta a Islen Vident'aqua a Los Baldíos.",
    [5159] = "Lleva el agua de poza de luna purificada a Greta Pezuñamusgo en Frondavil.",
    [5160] = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee.",
    [5161] = "Habla con Haleh si quieres continuar.",
    [5162] = "Habla con Jeziba en las Tierras de la Peste. Vive en Andorhal.",
    [5163] = "Coge el yeti mecánico de Umi y asusta con él a sus amigos: Legacki en Vista Eterna (Cuna del Invierno) Roxio en Gadgetzan (Tanaris) Quixxil en el Refugio de Marshal (Cráter de Un'Goro) Cuando hayas terminado, devuelve el yeti mecánico a Umi.",
    [5164] = "Lee el Catálogo del Díscolo.|n",
    [5165] = "Utiliza el agua de poza de luna purificada para apagar las llamas de los cuatro Blandones de Protección de la Guarida Sombría de Frondavil y vuelve con Greta Pezuñamusgo al Santuario Esmeralda.",
    [5166] = "Para forjar la coraza del Vuelo Cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos: 1 caparazón cromático. 10 escamas cromáticas luminosas. 10 sangres de héroes. 10 costuras desgarradas de abominación.",
    [5167] = "Para forjar los quijotes del desafiante cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos: 1 caparazón cromático. 10 escamas cromáticas brillantes. 10 sangres de héroes. 5 pieles de sombra.",
    [5168] = "Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana.",
    [5181] = "Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.",
    [5201] = "Rivern Ventogélido quiere que mates 5 chamanes Nevada y 5 ursas Nevada.",
    [5202] = "Recorre Jaedenar y descubre para qué se utiliza la llave roja de sangre.",
    [5203] = "Escolta a Arko'narin hasta el lugar en el que están Forjaluz y su equipo y protégela en la huida de la Guarida Sombría. Después, busca a Jessir Arcolunar en Frondavil para contarle lo que les ha ocurrido a sus amigos.",
    [5204] = "Vuelve a Jaedenar y mata al súcubo Rakaiah antes de encontrar los Restos de Trey Forjaluz.",
    [5206] = "Lleva 5 calaveras resonantes y el cristal místico a Carlin Rutagrana a las Tierras de la Peste del Este.",
    [5210] = "Lleva las Crónicas ampliadas de Villa Darrow a Carlin Rutagrana a las Tierras de la Peste del Este.",
    [5211] = "Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.",
    [5212] = "Consigue 20 muestras de carne apestadas de Stratholme y llévaselas a Betina Bigglezink. Tienes la sospecha de que podrás obtener ese tipo de carne de cualquier criatura de Stratholme.",
    [5213] = "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.|n",
    [5214] = "Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue.",
    [5215] = "Habla con la suma sacerdotisa MacDonnell en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5216] = "Ve al Campo de Piedra Mácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedra Mácula para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5217] = "Lleva la Botella rellena del Campo de Piedra Mácula a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5219] = "Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5220] = "Lleva la Botella rellena del Llanto de Dalson a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5222] = "Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5223] = "Lleva la Botella rellena de El Tormento a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5225] = "Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5226] = "Lleva la Botella rellena de la Gangrena de Gahrron a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5228] = "Habla con la sacerdotisa de las Sombras Vandis en el Baluarte, en las Tierras de la Peste del Oeste.",
    [5229] = "Ve al Campo de Piedra Mácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedra Mácula para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5230] = "Lleva la Botella rellena del Campo de Piedra Mácula a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste.",
    [5231] = "Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5232] = "Lleva la Botella rellena del Llanto de Dalson a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste.",
    [5233] = "Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5234] = "Lleva la Botella rellena de El Tormento a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste.",
    [5235] = "Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera.",
    [5236] = "Lleva la Botella rellena de la Gangrena de Gahrron a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste.",
    [5241] = "Encuentra a Carlin Rutagrana.",
    [5242] = "Mata a Moora y Salia y lleva la cabeza del Señor de las Sombras Fel'dan a Greta Pezuñamusgo a Frondavil.",
    [5243] = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.",
    [5244] = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz.",
    [5245] = "Utiliza el pico de Jaron para encontrar los cuatro fragmentos de reliquia de los altonatos. Llévaselas a Aurora Llamacielo en las Tierras de la Peste del Este.",
    [5246] = "Encuentra las escrituras altonatas sagradas del templo de Zin-Malor en Azshara y tráelas para Aurora Llamacielo, en la Torre del Paso Norte en las Tierras de la Peste del Este.",
    [5247] = "Consigue una barra encantada de torio, 5 cristales de restauración y un vial de agua funesta para Aurora Llamacielo, en la Torre del Paso Norte, en las Tierras de la Peste del Este.",
    [5248] = "Lleva el Cristal de Zin-Malor a Lago Kel'Theril en Cuna del Invierno y encuentra un espíritu altonato que hable contigo.",
    [5249] = "Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche.",
    [5250] = "Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche.",
    [5251] = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.",
    [5252] = "Habla con Wynd Cazanoche en Aldea Estrella Fugaz y pregúntale por el lugar adecuado para el Cristal de Zin-Malor.",
    [5253] = "Entrega el Cristal de Zin-Malor al archidruida Fandral Corzocelada de Darnassus.",
    [5261] = "Habla con Eagan Desollapieles.",
    [5262] = "Lleva la cabeza de Balnazzar al Duque Nicholas Zverenhoff en las Tierras de la Peste del Este.",
    [5263] = "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff.",
    [5264] = "Habla con Lord Maxwell Neófitus. Está en el interior de la iglesia.",
    [5265] = "Abre el Bastión Argenta y reclama tu recompensa.",
    [5281] = "Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme.",
    [5282] = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre. Libera 15 almas y regresa a Egan.",
    [5283] = "Para convertirte en <forjador/forjadora> de armaduras tienes que fabricar lo siguiente y llevárselo a Grumnus: 4 cascos, 2 botas y 1 peto de mitril ornamentado.",
    [5284] = "Para convertirte en armero tienes que fabricar lo siguiente y llevárselo a Ironus: 4 espadas de acero lunar, 4 hachas macizas de hierro, 2 hachas de mitril pesado y 2 grandes mazas negras.",
    [5301] = "Para convertirte en forjador de armaduras tienes que fabricar lo siguiente y llevárselo a Okothos: 4 cascos, 2 botas y 1 peto de mitril ornamentado.",
    [5302] = "Para convertirte en <forjador/forjadora> de armas tienes que fabricar lo siguiente y llevárselo a Borgosh: 4 espadas anchas de acero lunar, 4 hachas de hierro macizo, 2 hachas de mitril pesado y 2 mazas negras grandes.|n",
    [5305] = "Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith.|n",
    [5306] = "Viaja a la Cumbre de Roca Negra y mata a la cazadora de las Sombras Vosh'gajin. Recupera la piedra serpiente de Vosh'gajin y vuelve con Kilram.",
    [5307] = "Encuentra al armero Guardia Negra en Stratholme y acaba con él. Recupera la Insignia de La Guardia Negra y regresa con Seril Finiquiplaga.",
    [5321] = "Escolta a Kerlonian Semprumbrío por el camino meridional que lleva a Costa Oscura, donde Liladris Rioluna lo espera con su bolsa.",
    [5341] = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea.",
    [5342] = "Viaja al Campamento del Orvallo, territorio de la Alianza, y asesina a Weldon Barov. Coge su cabeza y regresa con Alexi Barov. Ten cuidado, Alexi seguramente estará muy protegido por la escoria de la Alianza.",
    [5343] = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea.",
    [5344] = "Viaja a El Baluarte, territorio de la Horda, y asesina a Alexi Barov. Coge su cabeza y regresa con Weldon Barov. Ten cuidado, Alexi seguramente estará muy protegido por la escoria de la Horda.",
    [5361] = "Entrégale el informe de Vigiarisco Cuernolargo a Nataka Cuernolargo que se encuentra en el Campamento del Espíritu Errante de Desolace.",
    [5381] = "Extrae la caja demoníaca de la Fortaleza del Hacha de Trueno y llévasela a Taiga Melenasabia a la Aldea Cazasombras junto con el Demon Pick.",
    [5382] = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.|n",
    [5384] = "Vuelve a Scholomance con la Sangre de los inocentes. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma. Lucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff.",
    [5385] = "Lleva los Restos de Trey Forjaluz a Jessir Arcolunar a Frondavil.",
    [5386] = "Habla con Jinar'Zillen, en la Aldea Cazasombras, y luego lleva 2 panzasangres a Nataka Cuernolargo.",
    [5441] = "Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos.",
    [5461] = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Recuerdo de Evocación. Si lo encuentras llévaselo al magistrado Marduke.",
    [5462] = "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Recuerdo de Evocación y cuéntale todo lo que has descubierto.",
    [5463] = "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Recuerdo de Evocación en suelo no consagrado.",
    [5464] = "Lleva las Memorias del Vínculo del Alma a Leonid Barthalomew a las Tierras de la Peste del Este.",
    [5465] = "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale las Memorias del Vínculo del Alma.",
    [5466] = "Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza las Memorias del Vínculo del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke.",
    [5481] = "Recoge 3 hierbas luminiscentes y entrégaselas al boticario de segunda Holland en el cementerio de Rémol.",
    [5482] = "Recoge 10 apocalíseas y entrégaselas al boticario de segunda Holland.",
    [5501] = "Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzbuckle a la Cabaña de Kormek.",
    [5504] = "Lleva 10 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5507] = "Lleva 10 muestras de valor del Alba Argenta al intendente Destello de Luz en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5513] = "Lleva 10 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.",
    [5514] = "Lleva los Fragmentos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan.",
    [5515] = "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff.",
    [5517] = "Lleva 25 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.",
    [5518] = "Lleva 4 madejas de paño rúnico, 8 retales de cuero basto, 2 hebras de hilo rúnico y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre.",
    [5521] = "Lleva 25 muestras de valor de El Alba Argenta al intendente Chispillo en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5522] = "Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este.",
    [5524] = "Lleva 25 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5526] = "Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de pureza para guardar el fragmento y llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna.",
    [5527] = "Ve a Silithus a buscar un relicario de pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna.",
    [5529] = "Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz.",
    [5531] = "Lleva los huevos congelados a Betina Bigglezink, que está fuera.",
    [5533] = "Habla con el alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5534] = "Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara.",
    [5535] = "Destruye 6 apariciones de Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara.",
    [5536] = "Mata 6 sátiros Haldarr, 2 timadores Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno.",
    [5537] = "Lleva 15 fragmentos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5538] = "Lleva los Fragmentos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan.",
    [5541] = "Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh.",
    [5542] = "Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring.",
    [5543] = "Mata 30 murcípestes y vuelve con Tirion Fordring.",
    [5544] = "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero.",
    [5545] = "Lleva 8 fajos de madera a Raelen al Aserradero de la Vega del Este.",
    [5561] = "Lleva 5 kodos domados y el kombobulador kodo a Smeed Mezclatornillos, al Campamento Mezclatornillos.",
    [5581] = "Destruye 6 Portales en el Aquelarre Mannoroc y vuelve a la Aldea Cazasombras a hablar con Taiga Melenasabia.",
    [5582] = "Lleva la escama sana de dragón a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.",
    [5601] = "Encuentra a Pamela Rutagrana en Villa Darrow.",
    [5621] = "Encuentra a la centinela Shaya y cura sus heridas utilizando un hechizo de Curación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo a Laurna Luzdelalba a Dolanaar.",
    [5622] = "Habla con Laurna Luzdelalba en Teldrassil.",
    [5623] = "Ve al Bosque de Elwynn y habla con la sacerdotisa Josetta.",
    [5624] = "Encuentra al guardia Roberts y cura sus heridas usando Curación inferior (Rango 2). Después, concédele la Palabra de poder: Entereza y vuelve a Villadorada a hablar con la sacerdotisa Josetta.",
    [5625] = "Encuentra al montaraz Dolf y cura sus heridas usando la Curación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Kharanos a hablar con Maxan Anvol.",
    [5626] = "Ve a Dun Morogh y habla con Maxan Anvol.",
