    [8236] = "Devuélvele la llave azur a Lord Jorach Ravenholdt.",
    [8240] = "Destruye una de las preseas Hakkari que hayas encontrado en Zul'Gurub en el Altar de Zanza en Isla Yojamba. Cuando lo hayas hecho ve a hablar con Vinchaxa.",
    [8250] = "Busca a Sanath Lim-yo y obtén permiso para ver al archimago Xylem.",
    [8251] = "Llévale 10 puñados de polvo relumbrante al archimago Xylem.",
    [8252] = "Reúne 6 corales encantados y llévaselos al archimago Xylem.",
    [8253] = "Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.",
    [8254] = "Busca a Ogtinc en Azshara.",
    [8255] = "Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.",
    [8256] = "Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.",
    [8257] = "Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas.",
    [8258] = "Usa el cristal de adivinación en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al caballero de la Muerte Atracoscuro, derrótalo. Llévale la cabeza de Atracoscuro a Sagorne Zanca Cresta en el Valle de la Sabiduría, en Orgrimmar.",
    [8275] = "Habla con Astaorgullo Clamavientos en el Fuerte Cenarion, en Silithus.",
    [8276] = "Habla con Astaorgullo Clamavientos en el Fuerte Cenarion, en Silithus.",
    [8277] = "Beetix Castaneo en el Fuerte Cenarion, en Silithus, quiere que consigas 8 aguijoneros escórpidos Latigosólido y 8 colmillos de arácnidos de arena. Vuelve a verla cuando hayas cumplido tu misión.",
    [8278] = "Beetix Castañeta en el Fuerte Cenarion, en Silithus quiere que consigas 3 aguijoneros de tenazario Latipiedra, 3 aguijoneros de despellejador Latipiedra y 3 colmillos de acecharrocas.",
    [8279] = "Lleva los tres capítulos del Lexicón del Crepúsculo a Hermit Ortell en Silithus.",
    [8280] = "Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 15 golpeadores deslizantes.",
    [8281] = "Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 20 trituradores deslizantes.",
    [8282] = "Recupera la Cartera de Noggle en las montañas al sur de Silithus y devuélvesela en el Fuerte Cenarion.",
    [8283] = "Lleva la pinza de Pinzamorten a Vish Kozus, Capitán de la guardia.",
    [8284] = "La Geóloga Trotuina en el Fuerte Cenarion, en Silithus, quiere que consigas 8 fragmentos de tablilla Crepuscular.",
    [8285] = "Lleva la tablilla restaurada al ermitaño Ortell en Silithus.|n",
    [8286] = "Ve a las Cavernas del Tiempo en Tanaris y encuentra a Anacronos, del Linaje de Nozdormu.",
    [8287] = "Lleva la trascripción de tablilla decodificada al comandante Mar'alith.",
    [8288] = "Lleva la cabeza del Señor de linaje Capazote a Baristolth del Mar de Dunas al Fuerte Cenarion en Silithus.",
    [8301] = "Lleva 200 fragmentos de caparazón de silítido a Baristolth.",
    [8302] = "Lleva 200 fragmentos de caparazón de silítido a Baristolth.",
    [8303] = "Busca a Anacronos en las Cavernas del Tiempo de Tanaris.",
    [8304] = "El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que interrogues a los habitantes del campamento Barbabronce, que está al sur del fuerte. Cuando consigas la información ve a ver al comandante Mar'alith.",
    [8305] = "Encuentra la lágrima cristalina en Silithus y mira en sus profundidades.",
    [8306] = "El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que encuentres a su amada Natalia. Parece que podría estar en Colmen'Regal, hacia el sur. No olvides ir a ver a los enanos del campamento Barbabronce antes de ir a la colmena; puede que tengan otras tareas o consejos que darte. Y recuerda lo que dijo el comandante: \"Haz lo que tengas que hacer.\"",
    [8307] = "Busca información sobre cómo cocinar carne de gusano de arena en el Campamento del Martillo Crepuscular, al oeste del Fuerte Cenarion.",
    [8308] = "Lleva la carta de Brann Barbabronce al campamento Barbabronce al sur de Silithus.",
    [8309] = "Rutgar Glifoforma del campamento Barbabronce en Silithus quiere que vayas a Colmen'Ashi, Colmen'Regal y Colmen'Zora y calques cristales en cada colmena. Usa el juego de calco para copiar los glifos antiguos. Vuelve a ver a Rutgar cuando hayas terminado la tarea.",
    [8310] = "Frankal Petraponte del campamento Barbabronce en Silithus quiere que le lleves 1 cerebro de silítido de Colmen'Zora, 1 de Colmen'Ashi y 1 de Colmen'Regal. Vuelve a ver a Frankal cuando hayas terminado la tarea.",
    [8313] = "Lleva la Página de receta rasgada a Calandrath en la taberna del Fuerte Cenarion.",
    [8314] = "Rutgar Glifoforma del campamento Barbabronce quiere que lleves el prisma cristalino con glifos a la geóloga Trotuina al Fuerte Cenarion de Silithus.",
    [8315] = "La Geóloga Trotuina del Fuerte Cenarion de Silithus quiere que consigas el mecanismo de desbloqueo de los cristales del emisario Qiraji. Tienes que llevar los glifos a Huesos de Grakkarond, al sur del Fuerte Cenarion, y dibujarlos en la arena. Si aparece el emisario Qiraji, mátalo y coge el mecanismo de desbloqueo de los cristales. Si lo consigues, ve a ver a la geóloga Trotuina. ¡Lleva un ejército contigo, <nombre>!",
    [8317] = "Calandrath, en el Fuerte Cenarion, necesita una entrega de 10 bolas de masa del desierto ahumadas.",
    [8318] = "Lleva 10 textos Crepusculares encriptados a Bor Bravacrín en el Fuerte Cenarion.",
    [8320] = "Mata 10 geoseñores Crepusculares y, a continuación, ve a ver a Huum Bravacrín en el Fuerte Cenarion.",
