    [8534] = "Contacta con la exploradora Cenarion Azenel en Colmen'Zora y entrega el informe de exploración de Colmen'Zora a Astaorgullo Clamavientos en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VI para poder completar la misión.",
    [8535] = "Invoca y mata a un Templario vetusto y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas IV para poder completar la misión.",
    [8536] = "Invoca y mata a un Templario de tierra y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas III para poder completar la misión.",
    [8537] = "Invoca y mata a un Templario carmesí y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas II para poder completar la misión.",
    [8538] = "Invoca y mata al Duque de las Brasas, al Duque de las Profundidades, al Duque de los Céfiros y al Duque de las Esquirlas y preséntate ante la comandante Mar'alith en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas V para poder completar la misión.",
    [8539] = "Mata 30 hermanas de la colmena de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate V para poder completar la misión.",
    [8540] = "Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión.",
    [8541] = "Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión.",
    [8542] = "Llévale 20 lingotes de estaño a Bruto Maug en el Valle de los Espíritus de Orgrimmar.",
    [8543] = "Llévale 20 lingotes de estaño al bruto Maug en Durotar.",
    [8544] = "Llévale las ataduras de mando qiraji, 2 ídolos de la noche, 5 escarabajos de piedra y 5 escarabajos de terracota a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión.",
    [8545] = "Llévale 20 lingotes de mitril al sargento jefe T'kelah en el Valle de los Espíritus de Orgrimmar.",
    [8548] = "Lleva 5 distintivos de combate Cenarion, 3 distintivos de logística Cenarion y 7 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación amistoso con el Círculo Cenarion para poder completar esta misión.",
    [8549] = "Llévale 20 flores de paz al herborista Plumorgullo en el Valle de los Espíritus de Orgrimmar.",
