    [8706] = "Llévale 1 empuñadura con púas qiraji, 2 ídolos de ámbar, 5 escarabajos de marfil y 5 escarabajos de bronce al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8707] = "Llévale 1 empuñadura ornamentada qiraji, 2 ídolos de obsidiana, 5 escarabajos de plata y 5 escarabajos de hueso al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8708] = "Llévale 1 empuñadura ornamentada qiraji, 2 ídolos de jaspe, 5 escarabajos de cristal y 5 escarabajos de piedra al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8709] = "Llévale 1 puño con pinchos qiraji, 2 ídolos bermellones, 5 escarabajos de oro y 5 escarabajos de terracota al celador Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8710] = "Llévale 1 empuñadura ornamentada qiraji, 2 ídolos de ónice, 5 escarabajos de oro y 5 escarabajos de terracota al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8711] = "Llévale 1 empuñadura con púas qiraji, 2 ídolos de ámbar, 5 escarabajos de bronce y 5 escarabajos de marfil al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8712] = "Llévale 1 puño con pinchos qiraji, 2 ídolos azures, 5 escarabajos de plata y 5 escarabajos de hueso al celador Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión.",
    [8728] = "Narain Sabelotodo de Tanaris quiere que le lleves 20 barras de arcanita, 10 menas de elementium, 10 diamantes de Azeroth y 10 zafiros azules.",
    [8729] = "Utiliza la boya de arcanita en La Vorágine espiral de la Bahía de la Tempestad de Azshara.",
    [8730] = "Mata a Nefarian y recupera del fragmento de cetro rojo. Llévaselo a Anacronos a las Cavernas del Tiempo, en Tanaris. Tienes 5 horas para completar esta tarea.",
    [8731] = "Preséntate ante Krug Machacacráneos en la Avanzada de la Legión de Orgrimmar delante de Colmen'Regal. Prepara tu documentación de instrucción de campo sin firmar, consigue la documentación de instrucción de campo firmada y llévaselas a Clamavientos Kaldon en el Fuerte Cenarion. Nota: curar o lanzar hechizos benéficos a un miembro de la Legión de Orgrimmar, te marcará como JcJ.",
    [8733] = "Viaja al continente de Teldrassil y busca al agente de Malfurion. Lo encontrarás a lo largo de los muros de Darnassus.|n",
    [8734] = "Ve a Claro de la Luna y habla con el guardián Remulos.",
    [8735] = "Ve a los 4 Portales del Sueño Esmeralda de Azeroth y recoge un fragmento de la corrupción de la Pesadilla en cada uno. Habla otra vez con el guardián Remulos en Claro de la Luna cuando hayas completado la tarea.",
    [8736] = "Defiende Amparo de la Noche de Eranikus. No dejes morir al guardián Remulos. No mates a Eranikus. Defiéndete. Espera a Tyrande.|n",
    [8738] = "Contacta con el explorador Cenarion Landion en Colmen'Regal y entrega el informe de exploración de Colmen'Regal a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VII para poder completar la misión.",
    [8739] = "Contacta con la exploradora Cenarion Jalia en Colmen'Ashi y entrega el informe de exploración de Colmen'Ashi a Astaorgullo Clamavientos en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VIII para poder completar la misión.",
    [8740] = "Mata a la Maleante Crepuscular Morna y a 5 Maleantes Crepusculares. Cuando termines tu tarea, entrégale el informe al Clamavientos Cuerno Digno. También debes llevar las Instrucciones de la misión táctica IX para poder completar la misión.",
    [8741] = "Lleva el fragmento de cetro verde a Anacronos a las Cavernas del Tiempo, en Tanaris.|n",
    [8771] = "Mata 30 acecharenas Colmen'Ashi y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate II para poder completar la misión.",
    [8772] = "Mata 30 oteadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VI para poder completar la misión.|n",
    [8773] = "Mata 30 atracadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IV para poder completar la misión.",
    [8774] = "Mata 30 emboscadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VIII para poder completar la misión.",
    [8775] = "Mata 30 escupefuegos Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IX para poder completar la misión.",
    [8776] = "Mata 30 esclavizadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate X para poder completar la misión.",
    [8777] = "Mata 30 hurgadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XI para poder completar la misión.",
    [8778] = "Lleva 6 aceites de inmolación, 5 unidades de combustible de cohete goblin y 10 unidades de pólvora densa al arcanista Bocafuente cerca de Colmen'Zora en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión.",
    [8779] = "Lleva 1 fragmento grande brillante, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión.",
    [8780] = "Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, cerca de Colmen'Zora, en Silithus. También debes llevar el Informe de tareas logísticas VII para poder completar la misión.",
    [8781] = "Lleva 2 espadas anchas de acero lunar a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, en las afueras de Colmen'Zora. También debes llevar el Informe de tareas logísticas VI para poder completar la misión.",
    [8782] = "Lleva 1 unidad de tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Astaorgullo Clamavientos en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión.",
    [8783] = "Lleva 2 lingotes de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión.",
    [8784] = "Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo.|n",
    [8785] = "Lleva 6 unidades de mojo potente, 6 frascos de mojo grande y 8 aceites de inmolación a la sacerdotisa de las Sombras Shai cerca de Colmen'Regal, en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión.",
    [8786] = "Lleva 3 hachas de hierro macizo a Merok Zancada Larga en el campamento de la Legión de Orgrimmar, en las afueras de Colmen'Regal. También debes llevar el Informe de tareas logísticas VI para poder completar la misión.",
    [8787] = "Lleva 8 complementos bastos para armadura y 8 complementos pesados para armadura a Merok Zancolargo, cerca de Colmen'Regal. También debes llevar el Informe de tareas logísticas VII para poder completar la misión.",
    [8789] = "Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas armamento imperial qiraji y 3 menas de elementium.",
    [8790] = "Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de Elementium para ti si le llevas regalos imperiales qiraji y 3 minerales de Elementium.",
    [8791] = "Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus.|n",
    [8792] = "Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar.",
    [8793] = "Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar.",
    [8794] = "Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar.",
