    [92709] = "Escucha lo que quiere contarte Elaadrin Vendaval del Atardecer en Valanaar.",
    [92727] = "Descubre qué fue de Fillion Brisallama.",
    [92741] = "Ve al Bosque Ventosombra y recoge 8 garfas de chilladora para Iaadaria Vientoamargo en Valanaar.",
    [92742] = "Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen.",
    [92743] = "Mantén tu reputación con los Magram y lleva una corona de conquistador de las Tierras Inhóspitas a Warug al Poblado Magram.",
    [92744] = "Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente.",
    [92745] = "Acaba con 4 cavadores kóbolds en la Mina de Jango y con 6 mineros Zarparrío en la Mina de la Costa del Oro.",
    [92747] = "Consigue 8 suministros industriales sospechosos en Arroyo de la Luna.",
    [92748] = "Viaja al Distrito de los Enanos de Ventormenta y busca a algún ingeniero que pueda ayudarte.",
    [92749] = "Consigue 10 unidades de dinamita férrea mediante fabricación, comercio o en la casa de subastas y luego vuelve con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.",
    [92750] = "Habla con alguien del servicio secreto de Ventormenta para conseguir un detonador a distancia.",
    [92751] = "Llévale el equipo de detonador a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.",
    [92752] = "Vuelve con Alba Lunajusta en los Páramos de Poniente.",
    [92753] = "Encuentra la forja oculta en las Minas de la Muerte y coloca los explosivos extradestructivos cerca. Luego, reúnete con Alba Lunajusta en la salida de las minas.",
    [92754] = "Mantén tu reputación con los Magram y lleva 3 pociones de protección contra las Sombras superiores a Mirda en el Poblado Magram de Desolace.",
    [92755] = "Mantén tu reputación con los Gelkis y lleva 3 esencias místicas superiores a Halea en el Poblado Gelkis de Desolace.",
    [92814] = "Mantén tu reputación con los Gelkis y lleva una máscara de bandido blanca a Molkar en el Poblado Gelkis de Desolace.",
    [92817] = "Mantén tu reputación con los Gelkis y lleva un arnés barbárico a Talra en el Poblado Gelkis de Desolace.",
    [92819] = "Utiliza el detonador.",
    [92834] = "Consigue 10 talismanes de piedra de viento de los cultores Al'Aketh que se encuentran al norte de Valanaar, en los campos de los Soplabayas o en el Santuario de Akir.",
    [92840] = "Lleva el Index Esoteria a las Piedras verticales del mirador de las Tierras Altas de Shen'dar y úsalo con las formaciones de piedras de viento de la zona para recopilar datos.",
    [92841] = "Mejora tu reputación con los Magram y busca a Orgrul cerca del Valle de los Huesos, al sur del Poblado Magram.",
    [92844] = "Mantén tu reputación con los Magram y lleva 426 huesos delicadamente malditos a Orgrul, al sur del Poblado Magram de Desolace.",
    [92846] = "Mantén tu reputación con los Magram y asesina nigromantes desterrados en el Valle de los Huesos.",
    [92849] = "Sigue buscando a Fillion Brisallama.",
    [92850] = "Mata a la matriarca chilladora en su guarida y luego entrega su cabeza a Fillion Brisallama, en Valanaar.",
    [92858] = "Llévale el bastón de Ohk'zi a Latronicus Lanzaluna en el Bastión Plumaluna de Feralas.",
    [92860] = "Informa a Valennia Puñotormenta y dile que la Orden Eminente la apoya en su lucha contra los Al'Aketh.",
    [92867] = "Derrota a los intrusos Puño de Roca, de la Hermandad y de los Secacorteza en el Castillo de Stromgarde. Después, vuelve con el guardés Lomar.",
    [92871] = "Informa a Valennia Puñotormenta y dile que los Formavientos la apoyan en su lucha contra los Al'Aketh.",
    [92872] = "Lanza la faltriquera de polvo de tumba al Mare Magnum y vuelve a ver al cuidador Alaric en la cripta del Castillo de Stromgarde.",
    [92878] = "Lleva una prueba de la muerte de Namida Tótem Siniestro a Blaise Montgomery en el Campamento Mojache.",
    [92880] = "Llévale el informe de Yorna a Valennia Puñotormenta en Valanaar.",
    [92881] = "Ve a Valanaar y habla con Talaanis Cantosombrío.",
    [92909] = "Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 14 isomuelles de gólem y 5 giroestabilizadores de cosechador.",
    [92910] = "Llévale el chasis de autocognición precesiva a Ozwin Ferropiñón, en la Granja de Saldean.",
    [92911] = "Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 8 isomuelles de gólem, 4 moduladores de cobre y una mira rudimentaria.",
    [92914] = "Explora Shen'dralas en busca de otros pilones como el que encontraste.",
    [92947] = "Acaba con 7 guardianes de Al'Aketh, 7 clamaespíritus de Al'Aketh y 7 maestros del acero de Al'Aketh, y luego informa a Hyusaa Brisa Presta en el Santuario de Akir.",
    [93016] = "Habla con Mordent Sombrapar en Shen'dralas para informarte sobre los cristales que has reparado.",
    [93034] = "Mejora tu reputación con los Gelkis y busca a Nerlokh cerca del Valle de los Huesos, al este del Poblado Gelkis.",
    [93035] = "Mantén tu reputación con los Gelkis y asesina a 6 devastadores no-muertos. Después, vuelve con Nerlokh en la entrada sur al Valle de los Huesos.",
    [93036] = "Habla con Sania Torrenteplata en la Aldea Shen'dar.",
    [93065] = "Habla con Valennia Puñotormenta en las Tierras Bajas de los Soplabayas.",
    [93089] = "Habla con Elaadrin Vendaval del Atardecer para partir de la Isla de Zephras.",
    [93090] = "Habla con Ayessa Cantoalba cuando estés preparada para marcharte de la Isla de Zephras.",
    [93159] = "Habla con el ermitaño extraño en el Bosque Ventosombra y averigua más cosas sobre él.",
    [93160] = "Recoge 8 bellotas ventosombra en el Bosque Ventosombra.",
    [93165] = "Consigue 5 orejas de cultores Al'Aketh en el Bosque Ventosombra, el Santuario de Akir o los Tierras Bajas de los Soplabayas.",
    [93172] = "Destruye 10 huecos ventosos en el Bosque Ventosombra.",
    [93176] = "Utilizando los objetos que contiene el kit de iniciación a la entomología, encuentra y atrapa un espécimen de tarántula arbórea, un gorgojo del heno y un recogedor de carne.",
    [93224] = "Consigue 5 tótems de los centauros tallados asesinando centauros de cualquier clan de Desolace y, luego, entrégaselos al capitán Pentigast en Punta de Nijel.",
    [93225] = "Consigue 5 tótems de los centauros tallados asesinando a centauros de cualquier clan de Desolace y, luego, entrégaselos a Gurda Ferocrín en el Campamento del Espíritu Errante.",
    [93226] = "Lleva la bolsa de tótems al intendente de los Magram en el Poblado Magram de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Magram.",
    [93227] = "Lleva la bolsa de tótems al intendente de los Gelkis en el Poblado Gelkis de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Gelkis.",
    [93317] = "Recoge 6 piezas de carne de reptador Canzalvaje.",
    [93318] = "Mata a Vulgara el Insaciable en las Tierras Altas de Shen'dar y lleva su cabeza a Danarii Velobramido.",
    [93319] = "Quita 10 piedras de viento birladas a los bandidos de las Tierras Altas en las Tierras Altas de Shen'dar.",
    [93320] = "Preséntate ante Yorana Juncoventoso en la torre de vigilancia oriental de las Tierras Bajas de los Soplabayas.",
    [93341] = "Investiga los Jardines Desolados cerca de Shen'dralas y luego vuelve con Mithera en el templo cercano.",
    [93362] = "Sacrifica las plantas de los Jardines Desolados y luego vuelve con Mithera en Shen'dralas.",
    [93394] = "Busca al magister Kirandis dentro del templo de Shen'dralas.",
    [93404] = "Adéntrate en Maraudon, recupera el vial de agua de Canto de la Tierra y llévaselo al ánima del bosque en los Jardines Desolados de Desolace.",
    [93429] = "Mata a 10 Perdidos en el Retiro Fangoso.",
    [93430] = "Encuentra al pescador Perdido que ha robado el cebo de Pelluk y devuélveselo.",
    [93443] = "Entrégale el cajón de transporte perdido a Friz Chispachás en Puerto Polvofusil, en Clarofluvial.",
    [93450] = "Coge la espada sin terminar de Vindael y encuentra un modo de llevarla al reino de los espíritus. Luego entrégale la hoja fantasmal en Shen'dralas.",
    [93461] = "Habla con Rathiril Lanzasol y Coriella Brisa Calmada en la Aldea Shen'dar.",
    [93464] = "Busca al mago en Desolace con conocimientos sobre el poder de la draenetista.",
    [93465] = "Recoge las notas sobre la draenetista de Gimashi y llévaselas a Azore Aldamort.",
    [93546] = "Busca depósitos de hierro espectral por Shen'dralas y reúne 10 menas de hierro espectral. Vuelve con Vindael en Shen'dralas cuando tengas suficiente.",
    [93552] = "Reúne 15 cúmulos de piedras de viento de las piedras de viento en bruto en la Arboleda Thendal.",
    [93568] = "Llévale la collera parcialmente digerida a alguien que sepa algo de ella. Supuestamente estará en Shen'dralas o cerca, en Desolace.",
    [93574] = "Encuentra a alguien a quien pueda interesarle el caparazón de Comecarroña.",
    [93585] = "Escolta al padre Tuttle hasta el Puerto.",
    [93594] = "Busca al ánima del bosque en los Jardines Desolados de Shen'dralas, en Desolace.",
    [93601] = "Busca un jabaespín importante en el Retiro Erizapúas.",
    [93604] = "Adéntrate en la Zahúrda Rajacieno, consigue la sangre de Agamaggan virulenta y llévasela a Kog'thug el Valiente en el Retiro Erizapúas de Desolace. Kog'thug te ha recordado que la sangre de Agamaggan dentro del Horado Rajacieno no servirá.",
    [93606] = "Apacigua la disputa de los jabaespines llevándole a Quolga un ramo benevolente y la sangre de Agamaggan virulenta. Puedes conseguir las flores para hacer el ramo en los Jardines Desolados, cerca de Shen'dralas, en Desolace.",
    [93609] = "Llévale el collar abandonado a Mithera en el templo de Shen'dralas, en Desolace.",
    [93644] = "El texto da a entender que el autor de este diario podría estar en algún lugar de Shen'dralas.",
    [93663] = "Busca al mensajero perdido y asegúrate de que el envío de Dar llega al Puerto.",
    [93678] = "Llévale las notas transcritas de Azore a Magtoor en el Puerto, en el Pantano de las Penas.",
    [93679] = "Contempla la visión de Onku con Magtoor.",
    [93680] = "Consigue la llave de las cloacas de Dalaran para el magus Wordeen Vacuamirada en Molino Tarren.",
    [93684] = "Encuentra al draenei que está buscando draenetista en las Tierras Devastadas.",
    [93735] = "Encuentra a Riaani Brisanoche en la zona oeste de Valanaar.",
