    [93737] = "Habla con Riaani Brisanoche y escucha lo que tiene que decirte.",
    [93738] = "Vuelve a Valanaar a informar a Ayessa Cantoalba.",
    [93739] = "Habla con Nazgrel en el Fuerte Grommash para que te dé indicaciones. Úsalas para localizar a Vol'jin, Cairne Pezuña de Sangre y Lady Sylvanas Brisaveloz y hablar con ellos.",
    [93740] = "Consigue 10 talismanes de piedra de viento de los cadáveres de los cultores Al'Aketh en los Tierras Bajas de los Soplabayas.",
