    [93786] = "Asesina a 12 mozos de labranza de Campoarroyo y luego vuelve a hablar con Krom'rosh.",
    [93787] = "Roba 6 bolsas para pienso de la granja de la Alianza en Campoarroyo y luego regresa con Krom'rosh.",
    [93788] = "Hazte con 10 hachas de leñador en el Aserradero de Turner y entrégaselas a Kreza Espinoscura en Rog'mar.",
