    [96775] = "Aniquila al médico brujo Zum'Rah y llévale su cabeza a Mazu'kon en Mulgore.",
    [96776] = "Recupera el cristal conocido como resplandor de An'she de Maraudon.",
    [96779] = "Encuentra a lord Tomas en el Castillo de Durnholde de las Laderas de Trabalomas y mátalo. Después, informa a Myrokos Silenforma.",
    [96781] = "Roba el informe de exploración de Barton. Después, informa a Myrokos Silenforma en la Mansión Ravenholdt.",
    [96782] = "Encuentra la hoja de la Casa Perenolde y la égida real de Perenolde en las ruinas de Alterac y entrégaselas a Myrokos Silenforma.",
    [96783] = "Roba un uniforme de la Hermandad en la Mansión Redilnorte e infíltrate en el Castillo de Stromgarde.",
    [96784] = "Mientras te haces pasar por un miembro de la Hermandad, encuentra a alguien dentro del Castillo de Stromgarde que esté al corriente del acuerdo secreto.",
    [96785] = "Encuentra algo en el Castillo de Stromgarde para convencer a Anastasia de que te revele los detalles del acuerdo secreto.",
    [96786] = "Frustra el trato secreto y toma el objeto de la Hermandad. Después, entrégaselo a Myrokos Silenforma en la Mansión Ravenholdt.",
    [96797] = "Viaja al Castillo de Nethergarde en las Tierras Devastadas y busca al sargento Danneth.",
    [96798] = "Encuentra al sargento Danneth en las cavernas de Serpiente Enroscada, al sureste del Castillo de Nethergarde.",
    [96799] = "Habla con el sargento Danneth en el Castillo de Nethergarde.",
    [96800] = "Recupera el libro \"La magia perdida de los maestros de runas\" para el Monasterio Escarlata.",
    [96811] = "Escolta al sargento Danneth para salir de las cuevas de Serpiente Enroscada y llegar al Castillo de Nethergarde.",
    [96812] = "Vuelve con la supervisora de huérfanos Aria en Dalaran y cuéntale que el sargento Danneth está dispuesto a acoger a Randal.",
    [96821] = "Mata a 6 trepadores crestasombra y a 6 rondadores crestasombra en la parte sur de Durotar. Después, informa a Gar'thok en Cerrotajo.",
    [96822] = "Consigue el hacha de batalla de asaltante, el arco de asaltante y el escudo de asaltante a las afueras del Fuerte de Tiragarde y devuélveselo todo a Turroc en Cerrotajo.",
    [96825] = "El cocinero Torka de Cerrotajo quiere que recojas 8 frutos pera espinosa en las Tierras Crines de Acero que hay al oeste de la ciudad.",
    [96873] = "Pa'zula, en el Poblado Sen'jin, quiere que reúnas 3 de residuo luminoso. Se puede obtener residuo luminoso desencantando los colgantes embrujados que dejan caer los trols en las Islas del Eco.",
    [96874] = "Ug'thok en Orgrimmar quiere que consigas 5 espinazos deteriorados de las bestias que hay en Monte del Trueno y 5 piedras de pulir férreas.",
    [96875] = "Kamari en Orgrimmar quiere que consigas 5 pellejos de lagarto resistentes de las bestias que hay en Monte del Trueno y 2 pellejos ligeros curados.",
    [96876] = "Devuélvele la bolsa a Ukor en la parte sur de Durotar.",
    [96877] = "Entrega la pezuña de Halikor en Orgrimmar.",
    [96895] = "Encuentra al miembro de El Alba Argenta cerca de la entrada de Entrañas.",
    [96896] = "Observa la conversación entre Danitha Morr y Leonid Barthalomew el Venerado.",
    [96897] = "Mata a 8 neófitos oscuros y a 8 déspotas oscuros en los Claros de Tirisfal.",
    [96898] = "Consigue 12 trozos de cristal necrótico en los Claros de Tirisfal.",
    [96899] = "Reúnete con Leonid Barthalomew en la Fortaleza de Bandarion, en los Claros de Tirisfal.",
    [96984] = "Recupera la mota Arcana en la Ciudad de Dalaran para el magus Wordeen Vacuamirada, en Molino Tarren.",
    [96986] = "Derrota a Atrexis el Caballero de la Tumba en la Ciudad de Dalaran. Después, informa a Melisara en Molino Tarren.",
    [96987] = "Consigue La fundación de Dalaran en la Ciudad de Dalaran para Rexxie Aferracobre, en la entrada a las cloacas.",
    [96988] = "Consigue 6 núcleos de centinela agrietados en la Ciudad de Dalaran para el doctor Martin Felben de Entrañas.",
    [96996] = "Observa a los zancavendavales y elige tu primera montura.",
    [96997] = "Observa a los caballos de montar no-muertos y elige tu primera montura.",
    [97003] = "Lleva la cabeza de Chol'aruk a Gur'ak en Los Baldíos.",
    [97005] = "Lleva la cabeza de Chol'aruk a Bainham en Los Baldíos.",
    [97017] = "Observa a los carneros de montar y elige tu primera montura.",
    [97018] = "Aprende la habilidad Aprendiz jinete de Ulthaan Ferrocorno.",
    [97022] = "Habla con Danitha Morr en la Fortaleza de Bandarion.",
    [97045] = "Observa a los caballos de montar y elige tu primera montura.",
    [97046] = "Observa a los mecazancudos y elige tu primera montura.",
    [97047] = "Busca en la Base de Kurzen la llave que abre la jaula de Wendel y un disfraz con el que pueda salir sin levantar sospechas.",
    [97048] = "Habla con la capitana Aransas en Bahía del Botín.",
    [97074] = "Aprende la habilidad Aprendiz jinete de Jartsam.",
    [97130] = "Recupera un antiguo ídolo Gurubashi en la Ciudad Sumergida.",
    [97170] = "Aprende la habilidad Aprendiz jinete de Randal Predatio.",
    [97173] = "Recupera un tótem de ritual Faucenegra en el Bastión Faucenegra.",
    [97188] = "Aprende la habilidad Aprendiz jinete de Binjy Plumasilba.",
    [97196] = "Recupera el ojo del Gélido en la Zahúrda Rajacieno.",
    [97197] = "Recupera un fragmento de las Tierras de Fuego de las Profundidades de Roca Negra y llévaselo a Alaana Caminatormentas en Mulgore.",
    [97198] = "Recupera un tótem de ritual Faucenegra en el Bastión Faucenegra.",
    [97203] = "Aprende la habilidad Aprendiz jinete de Velma Warnam.",
    [97205] = "Aprende la habilidad Aprendiz jinete con Genn Buentiempo.",
    [97220] = "Lleva el envío a la torre de entrada a la entrada del almacén ubicada en la tienda Queso de Trias, en el Distrito de Mercaderes.",
    [97222] = "Lleva el envío a la torre de entrada en el piso de arriba de la tienda Queso de Trias y déjalo en la puerta.",
    [97223] = "Llévale los huevos de la matriarca Garrasangre a Xar'Ti, en el Poblado Sen'jin.",
    [97225] = "Reúne 8 ídolos loa olvidados en las Islas del Eco. Llévaselos a maese Gadrin al Poblado Sen'jin.",
    [97234] = "Lleva el material de lectura envuelto a la biblioteca de Ventormenta.",
    [97236] = "Entrega el colmillo de Githyiss a alguien que esté interesado en el estudio de las arañas en Aldrassil.",
    [97237] = "Encuentra todos los materiales de lectura que se encuentran por la biblioteca y vuelve con Roy Lewells en el Parque de Ventormenta.",
    [97242] = "Recoge algunos esquejes de las apiáceas y de las eneas que crecen alrededor del estanque del Valle del Honor y entrégaselos a Kor'geld en la tienda de Alquimia y pociones de Yelmak.",
    [97243] = "Llévale la antorcha de la llama latente a Olariaan Ardeveloz en el santuario de las llamas que está en las Tierras Bajas de los Soplabayas.",
    [97244] = "Asesina al sacerdote del cielo Faladiel en las Tierras Bajas de los Soplabayas y consigue su corazón.",
    [97245] = "Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota a este espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Ardeveloz en las Tierras Bajas de los Soplabayas una vez que te alces con la victoria.",
    [97246] = "Visita la Fosa de lava de Borstan y dile que Thatog quiere que le entregues personalmente el almuerzo de Migi.",
    [97249] = "Llévale el almuerzo a Migi detrás del Fuerte Grommash.",
    [97250] = "Mata a los soldados de la Alianza que han invadido Los Baldíos en la frontera con el Marjal Revolcafango y luego vuelve con el bruto Logmar en el Campamento Taurajo.",
    [97253] = "Consigue 5 puñados de piezas complicadas del campamento pirata superior que hay al sur de Trinquete y luego vuelve con Desdio el Desdichado en Trinquete.",
    [97257] = "Espera a que Olariaan empiece el ritual en el blandón de ofrendas y sigue sus instrucciones. Debes entregar la Llama eterna en Valanaar antes de que se agote el tiempo.",
    [97263] = "Entrega a Eldrun su paquete perdido.",
    [97265] = "Derrota a sátiros Odio Feroz en Sargeron, Desolace, y luego vuelve con Aka'rai en la Aldea Cazasombras.",
    [97275] = "Dale la poción de Yelmak a Whuut.",
    [97277] = "Busca el campamento de Grund y Gozwin en las colinas que hay al noroeste. Recupera el registro de mecánico de Gozwin y mata al leopardo de la nieve merodeador.",
    [97279] = "Recoge 6 armas de entrenamiento abandonadas y llévaselas a Kzan Trallafusta en El Cubil.",
    [97281] = "Llévale el orbe de tormenta sin brillo a Rezlak, cerca del Barranco Árido.",
    [97282] = "Llévale 5 órganos de truenagarto cargados a Rezlak, cerca del Barranco Árido.",
    [97284] = "Mata a los orcos del Filo Ardiente de la Fortaleza del Hacha de Trueno de Desolace y después vuelve con Vahlarriel Destripademonios en Punta de Nijel.",
    [97287] = "Habla con la imagen de la archimaga Modera cerca de Dalaran.",
    [97288] = "Entrega la cabeza abominable al maestro boticario Faranell en Entrañas.",
    [97289] = "Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas.",
    [97290] = "Informa de tus hallazgos al maestro boticario Faranell de Entrañas.",
    [97291] = "Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.",
    [97292] = "Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell.",
    [97326] = "Llévale 8 rocas suaves a Thra detrás del Fuerte Grommash.",
    [97328] = "Recupera 8 envíos robados de las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévaselos a alguien en Bahía del Botín.",
    [97329] = "Consigue la llave primitiva de los trols en las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévasela a Zimmix Escupechispa.",
    [97331] = "Escolta a Zimmix Escupechispa fuera de las Ruinas de Zul'Kunda e informa al jefe de embarcadero Lozgil del éxito de tu rescate en Bahía del Botín.",
    [97332] = "Entrega el paquete pedido dos veces al maestro de los muelles Silbazumbido en Puerto Polvofusil, en Clarofluvial.",
    [97378] = "Llévale el ala de Escamarreflejo a Melor Pezuñapétrea en Cima del Trueno.",
    [97386] = "El comandante del Campamento Grom'gol, Aggro'gosh, quiere que mates ogros en el Túmulo Ogro Mosh'Ogg.",
    [97405] = "Knaz Flamerrada quiere que mates 3 creaconjuros Mosh'Ogg, 3 belicistas Mosh'Ogg, 3 aplastadores Mosh'Ogg y 3 chamanes Mosh'Ogg en el Túmulo Ogro Mosh'Ogg.",
    [97420] = "Consigue 4 bidones de petróleo de las operaciones de Ventura y Cía. en el Lago Nazferiti y vuelve con Knaz Flamerrada en la Vega de Tuercespina.",
    [97453] = "Mata 6 hierbas carnívoras al sur de Grom'gol e informa a la madre de Gemmil.",
    [97485] = "Compra un fardo de hierbas a Nida la herborista, un fardo de ramas de cedro a Nata la proveedora de encantamientos, hilo tendinoso a Mahu el proveedor de suministros de peletería, y sílex y yesca ceremoniales a Naal el proveedor de artículos de cocina. Combina los objetos y esparce el incienso desde el Alto de los Cazadores.",
    [97530] = "El jefe de seguridad Pasaquillas del Puerto Bonvapor, en Tanaris, te pide que recuperes un brazalete brillante que se extravió cerca del hábitat de los ogros Machacadunas.",
    [97534] = "Quinn quiere que consigas 7 unidades de escombros del desierto y se las lleves a Gadgetzan.",
    [97536] = "Jhordy Mantoforja quiere que acudas a informarle cuando hayas tirado el cajón de desechos radiactivos en el desierto de Tanaris, a una distancia segura de Gadgetzan y de otros residuos.",
    [97538] = "Tah Pezuña Invernal en Cima del Trueno quiere 30 vainas de hierbaoscura del Lago Mirkfallon.",
    [97539] = "Entrega 12 sedas de araña quirúrgicas al doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi.",
    [97540] = "Ahora que Tooga ha colmado su sed, llévalo de vuelta con su mujer, Thorta.",
    [97558] = "Lleva 8 membranas de ala de murciumbrío, 6 pellejos de can oscuro y 3 piel de múrloc Anca Vil a Shelene Rhobart.",
    [97583] = "Compra fango de babosa nutritivo y vuelve con tu inquieta y amistosa babosa. Si parece cansada, baila con ella de nuevo para llamar su atención.",
    [97617] = "Llévale 8 artefactos sin estudiar, un casco de minería de la Liga de Expedicionarios y un azadón prístino a Dorgaron, que está en la frontera entre Loch Modan y las Tierras Inhóspitas.",
    [97663] = "Mata ogros en Terraseca para recuperar los suministros robados de Mus'hale y utilízalos para hacer calcos de los grabados de piedra cercanos. Después, vuelve con Mus'hale en Kargath.",
    [97884] = "Viaja a Clarosol en Clarofluvial y recupera el escrito Técnicas de herrería de la familia Tremayne.",
    [97891] = "Llévale una poción inestable al doctor Martin Felben en El Apothecarium antes de que se acabe el tiempo.",
    [97894] = "Comprueba cómo está Gorbold Mano de Acero en Auberdine, en Costa Oscura. Borgus ha mencionado que puedes coger un barco en el muelle más al sur del Puerto de Ventormenta.",
